    await ctx.tx.query("update erp.animals set category_id=coalesce($3,category_id), breed_id=coalesce($4,breed_id), batch_id=coalesce($5,batch_id), sex=coalesce($6,sex), birth_date=coalesce($7,birth_date), reproductive_stage=coalesce($8,reproductive_stage), reproductive_status=coalesce($9,reproductive_status), current_weight=coalesce($10,current_weight), price_arroba_alive=coalesce($11,price_arroba_alive), unit_value=coalesce($12,unit_value), fur_description=coalesce($13,fur_description), birth_forecast=coalesce($14,birth_forecast), proprietary_id=coalesce($15,proprietary_id), note=coalesce($16,note), updated_at=now() where id=$1 and organization_id=$2", [id, ctx.orgId, d.category_id ?? null, d.breed_id ?? null, d.batch_id ?? null, d.sex ?? null, d.birth_date ?? null, d.reproductive_stage ?? null, d.reproductive_status ?? null, d.current_weight ?? null, d.price_arroba_alive ?? null, d.unit_value ?? null, d.fur_description ?? null, d.birth_forecast ?? null, d.proprietary_id ?? null, d.note ?? null]);
