  app.get("/livestock/herd-lots", async (req) => runService(app, req, "animals.view", async (ctx) => { const r = await ctx.tx.query("select h.*, c.name as category_name, b.name as breed_name, bt.description as batch_name, f.name as farm_name from erp.herd_lots h join erp.animal_categories c on c.id=h.category_id left join erp.breeds b on b.id=h.breed_id left join erp.batches bt on bt.id=h.batch_id join erp.farms f on f.id=h.farm_id where h.organization_id=$1 and h.quantity>0 and ($2::uuid[] is null or h.farm_id = any($2)) order by f.name, c.name", [ctx.orgId, allowedFarms(ctx)]); return { items: r.rows, total: r.rowCount, total_quantity: r.rows.reduce((a, x) => a + (x as { quantity: number }).quantity, 0) }; }));
