  app.get("/livestock/locate", async (req) => runService(app, req, "locate_animals.view", async (ctx) => { const { search } = req.query as { search?: string }; if (!search) return { items: [] }; const r = await ctx.tx.query("select a.id, a.status, i.value as identification, t.name as identification_type, f.name as farm_name, bt.description as batch_name, gm.description as module_name, ar.name as area_name, c.name as category_name from erp.animal_identifications i join erp.animals a on a.id=i.animal_id join erp.identification_types t on t.id=i.identification_type_id join erp.farms f on f.id=a.farm_id left join erp.batches bt on bt.id=a.batch_id left join erp.grazing_modules gm on gm.id=bt.grazing_module_id left join erp.areas ar on ar.id=bt.area_id join erp.animal_categories c on c.id=a.category_id where i.organization_id=$1 and i.value ilike $2 and ($3::uuid[] is null or a.farm_id = any($3)) limit 50", [ctx.orgId, `%${search}%`, ctx.membership.farmIds.length ? ctx.membership.farmIds : null]); return { items: r.rows }; }));

