    const { id } = req.params as { id: string }; const d = z.object({ animals: z.array(z.object({ herd_lot_id: uuid, category_id: uuid, breed_id: uuid.optional().nullable(), sex: z.enum(["M", "F"]).optional().nullable(), weight: dec.optional().nullable(), batch_id: uuid.optional().nullable(), identifications: z.array(z.object({ identification_type_id: uuid, value: z.string().min(1) })).min(1) })).min(1), finish: z.boolean().default(false) }).parse(req.body);
